  const DUCK = Math.pow(10, CONFIG.music.duckDb / 20);
  const musicLevel = () => (A.musicOn ? CONFIG.music.gain : 0) * (A.ducked ? DUCK : 1) * A.wxDuck;   // nhạc nền: giọng thuyết minh và bão cùng hạ


