  fb: P.fb, fbd: P.fbd, fbAt: P.fbAt || [], whoLive: (() => { const m = {}; for (const w of (P.who || new Map()).values()) m[w] = (m[w] || 0) + 1; return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, 12); })(), playout: P.ctx.playoutStats ? JSON.parse(JSON.stringify(P.ctx.playoutStats)) : null }; });
console.log(`intro chạy ${((Date.now() - t0) / 1000).toFixed(1)} s thật, ${R.sr} Hz; nguồn đang chạy cuối ${R.live}, nhiều nhất ${R.maxLive}, tổng nguồn tạo ${R.made}; nhạc: ${JSON.stringify(R.stat)}`);
