function build() {
  const AC = (window.AudioContext || (window as unknown as { webkitAudioContext: AudioCtor }).webkitAudioContext);
  let ctx: AudioContext;
  try { ctx = new AC({ latencyHint: latencyHint() }); } catch { ctx = new AC(); }
  A.ctx = ctx;

