  await p.keyboard.press('Space'); await p.waitForTimeout(500); s = await st(); chk(`${lang}: tiếp tục`, !s.paused && s.on);
  for (let k = 0; k < 6; k++) { await p.keyboard.press('ArrowRight'); await p.waitForTimeout(700); }
  s = await st(); chk(`${lang}: tua tới nhịp 6 (Cầu Rồng)`, s.i === 6, `i=${s.i}`);
  await p.waitForTimeout(6000); await p.keyboard.press('ArrowRight'); await p.waitForTimeout(3000); await p.keyboard.press('ArrowLeft'); await p.waitForTimeout(800);
  s = await st(); chk(`${lang}: lui về nhịp 6`, s.i === 6, `i=${s.i}`);
  await p.keyboard.press('Escape'); await p.waitForTimeout(1000);
  s = await p.evaluate(() => ({ active: window.__app.intro.active, on: window.__app.audio.on, chooser: !document.getElementById('chooser')?.hidden }));
  chk(`${lang}: Bỏ qua → màn chọn, âm thanh vẫn bật`, !s.active && s.on && s.chooser, JSON.stringify(s));
  await p.click('#exIntroBtn'); await p.waitForTimeout(1500);
  s = await p.evaluate(() => ({ active: window.__app.intro.active, i: window.__app.intro.clock.i, on: window.__app.audio.on, ctxs: window.__ctxCount }));
  chk(`${lang}: Xem lại → intro chạy lại từ nhịp 0, cùng ngữ cảnh`, s.active && s.i === 0 && s.on, JSON.stringify(s));
  await p.evaluate(() => window.__app.intro.seek(8)); await p.waitForTimeout(8000);
  s = await st(); chk(`${lang}: tới nhịp kết, nhạc không bỏ bước`, s.i === 8 && s.sk === 0, `skipped=${s.sk}`);
  chk(`${lang}: không lỗi trang / console`, errs.length === 0, errs.slice(0, 3).join(' | '));
  await p.close();
}
await b.close(); srv.close(); console.log(ok.every(Boolean) ? 'TẤT CẢ ĐẠT' : 'CÓ LỖI');
EOF
