p='src/audio/music.ts'
s=open(p,encoding='utf8').read()
old_noise="  const noise = (buf: AudioBuffer, t: number, dur: number) => { const s = ctx.createBufferSource(); s.buffer = buf; s.start(t, rnd() * 1.5); s.stop(t + dur); return s; };"
assert old_noise in s
new_noise = old_noise + """
  /* Nhiễu trắng lọc sẵn một lần cho tiếng trống có bộ lọc tần số cố định (hi-hat, lắc, snare, crash): bỏ một BiquadFilter mỗi tiếng — loại nút đắt nhất trên luồng âm thanh,
     và với lookahead 2 s mỗi khối 2,67 ms phải xử lý cả các nốt đang chờ. Hệ số đúng công thức biquad của Web Audio (Q của highpass tính bằng dB, bandpass tuyến tính),
     chạy qua bộ đệm hai lượt để lấy trạng thái dừng: phổ như lọc trực tiếp, chỉ khác quá độ vài mẫu đầu của bộ lọc mới tạo (không nghe thấy) */
  const preNoise = new Map<string, AudioBuffer>();
  function filtered(type: 'highpass' | 'bandpass', f0: number, q: number): AudioBuffer {
    const key = `${type}|${f0}|${q}`, hit = preNoise.get(key); if (hit) return hit;
    const src = deps.white.getChannelData(0), n = src.length, sr = deps.white.sampleRate, w = 2 * Math.PI * f0 / sr, cw = Math.cos(w), sw = Math.sin(w);
    const al = type === 'highpass' ? sw / (2 * Math.pow(10, q / 20)) : sw / (2 * q);
    const a0 = 1 + al, a1 = -2 * cw / a0, a2 = (1 - al) / a0;
    const b0 = (type === 'highpass' ? (1 + cw) / 2 : al) / a0, b1 = (type === 'highpass' ? -(1 + cw) : 0) / a0, b2 = (type === 'highpass' ? (1 + cw) / 2 : -al) / a0;
    const buf = ctx.createBuffer(1, n, sr), o = buf.getChannelData(0);
    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    for (let pass = 0; pass < 2; pass++) for (let i = 0; i < n; i++) { const x = src[i], y = b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2; x2 = x1; x1 = x; y2 = y1; y1 = y; if (pass) o[i] = y; }
    preNoise.set(key, buf); return buf;
  }"""
