import { chromium } from 'playwright';
const b = await chromium.launch(); const p = await b.newPage();
console.log(await p.evaluate(async () => {
  const sr = 48000, n = sr * 2, out = [];
  for (const [type, f0, q] of [['highpass', 7500, 1], ['bandpass', 5200, 1.2], ['bandpass', 1900, 0.7], ['bandpass', 2600, 0.7], ['highpass', 4800, 1]]) {
    const ctx = new OfflineAudioContext(1, n * 2, sr), wb = ctx.createBuffer(1, n, sr), w = wb.getChannelData(0); for (let i = 0; i < n; i++) w[i] = Math.random() * 2 - 1;
    const s = ctx.createBufferSource(); s.buffer = wb; s.loop = true; const f = ctx.createBiquadFilter(); f.type = type; f.frequency.value = f0; f.Q.value = q; s.connect(f).connect(ctx.destination); s.start();
    const ref = (await ctx.startRendering()).getChannelData(0).subarray(n);   // lượt 2: trạng thái dừng
    const W = 2 * Math.PI * f0 / sr, cw = Math.cos(W), sw = Math.sin(W), al = type === 'highpass' ? sw / (2 * Math.pow(10, q / 20)) : sw / (2 * q);
    const a0 = 1 + al, a1 = -2 * cw / a0, a2 = (1 - al) / a0, b0 = (type === 'highpass' ? (1 + cw) / 2 : al) / a0, b1 = (type === 'highpass' ? -(1 + cw) : 0) / a0, b2 = (type === 'highpass' ? (1 + cw) / 2 : -al) / a0;
    const o = new Float32Array(n); let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    for (let pass = 0; pass < 2; pass++) for (let i = 0; i < n; i++) { const x = w[i], y = b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2; x2 = x1; x1 = x; y2 = y1; y1 = y; if (pass) o[i] = y; }
    let e = 0, r = 0; for (let i = 0; i < n; i++) { e += (o[i] - ref[i]) ** 2; r += ref[i] ** 2; }
    out.push(`${type} ${f0} Q${q}: sai khác ${(10 * Math.log10(e / r)).toFixed(1)} dB so với tín hiệu`);
  }
  return out.join('\n');
}));
await b.close();
EOF
